def search_insert(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

def count_palindromic_words(text):
    words = [w.lower() for w in text.split() if w.isalnum()]
    return sum(1 for w in set(words) if w == w[::-1])

