from collections import deque
def has_cycle(adj):
    visited = set()
    for start in adj:
        if start in visited:
            continue
        queue = deque([(start, -1)])
        visited.add(start)
        while queue:
            u, parent = queue.popleft()
            for v in adj.get(u, []):
                if v not in visited:
                    visited.add(v)
                    queue.append((v, u))
                elif v != parent:
                    return True
    return False
